use gloo_net::http::Request;
use leptos::{mount::mount_to_body,prelude::*};
use serde::Deserialize;
use wasm_bindgen_futures::spawn_local;
#[derive(Clone,Debug,Deserialize,PartialEq)]
#[serde(rename_all="camelCase")]
struct Movie{slug:String,name:String,#[serde(default)]origin_name:String,#[serde(default)]poster:String,#[serde(default)]backdrop:String,#[serde(default)]year:Option<i32>,#[serde(default)]quality:String,#[serde(default)]current_episode:String,#[serde(default)]time:String}
#[derive(Deserialize)]struct MovieList{#[serde(default)]items:Vec<Movie>}
#[derive(Clone,Debug,Deserialize)]struct Episode{#[serde(default)]name:String,#[serde(default)]embed:String,#[serde(default)]m3u8:String}
#[derive(Clone,Debug,Deserialize)]struct Server{#[serde(default)]name:String,#[serde(default)]episodes:Vec<Episode>}
#[derive(Clone,Debug,Deserialize)]struct DetailMovie{#[serde(default)]name:String,#[serde(default)]content:String,#[serde(default)]year:Option<i32>,#[serde(default)]time:String,#[serde(default)]quality:String,#[serde(default)]actors:Vec<String>,#[serde(default)]directors:Vec<String>}
#[derive(Clone,Debug,Deserialize)]struct Detail{movie:DetailMovie,#[serde(default)]servers:Vec<Server>}

#[derive(Clone)]
struct ShelfData { id: String, title: String, items: Vec<Movie> }

#[component]
fn HomeShelf(id: String, title: String, items: Vec<Movie>, on_open: Callback<Movie>) -> impl IntoView {
    let cards = items.into_iter().take(12).map(|movie| {
        let selected = movie.clone();
        let callback = on_open;
        let title = movie.name.clone();
        let poster = movie.poster.clone();
        let quality = movie.quality.clone();
        let year = movie.year.map(|v| v.to_string()).unwrap_or_default();
        let episode = movie.current_episode.clone();
        view! {
            <button class="shelf-card" on:click=move |_| callback.run(selected.clone())>
                <div class="poster"><img src=poster alt=title.clone() loading="lazy"/><b>{quality}</b><i>"▶"</i></div>
                <strong>{title}</strong>
                <small>{year} " · " {episode}</small>
            </button>
        }
    }).collect_view();
    view! { <section class="home-shelf" id=id><div class="shelf-heading"><h2>{title}</h2><a href="#top">Khám phá <span>"›"</span></a></div><div class="shelf-track">{cards}</div></section> }
}
fn enc(s:&str)->String{s.replace('%',"%25").replace(' ',"%20").replace('&',"%26").replace('#',"%23").replace('?',"%3F")}
#[component]fn App()->impl IntoView{
 let(movies,sm)=signal(Vec::<Movie>::new());let(loading,sl)=signal(true);let(query,sq)=signal(String::new());let(tab,st)=signal("home".to_string());let(hero_index,shi)=signal(0usize);let(selected,ss)=signal(Option::<Movie>::None);let(detail,sd)=signal(Option::<Detail>::None);let(playing,sp)=signal(String::new());let(notice,sn)=signal(String::new());
 let shelf_defs:Vec<(&'static str,&'static str,&'static str)>=vec![
 ("shelf-korea","Điện ảnh Hàn Quốc","quoc-gia:han-quoc"),("shelf-china","Mọt phim Hoa Ngữ","quoc-gia:trung-quoc"),
 ("shelf-anime","Thế giới Anime","the-loai:hoat-hinh"),("shelf-horror","Đêm Kinh Hoàng","the-loai:kinh-di"),
 ("shelf-action","Hành Động Nghẹt Thở","the-loai:hanh-dong"),("shelf-romance","Tình cảm lãng mạn","the-loai:tinh-cam"),
 ("shelf-usuk","Phim US-UK mới","quoc-gia:au-my"),("shelf-thai","Thiên đường Phim Thái","quoc-gia:thai-lan"),
 ("shelf-vietnam","Dấu ấn điện ảnh Việt","quoc-gia:viet-nam"),("shelf-costume","Cổ trang đặc sắc","the-loai:co-trang"),
 ("shelf-mystery","Trinh thám & Bí ẩn","the-loai:hinh-su"),("shelf-japan","Mê Cung Phim Nhật","quoc-gia:nhat-ban")
 ];
 let(home_shelves,shs)=signal(shelf_defs.iter().map(|(id,title,_)|ShelfData{id:(*id).into(),title:(*title).into(),items:Vec::new()}).collect::<Vec<_>>());
 let load=move|q:String,kind:String|{sl.set(true);let url=if q.trim().is_empty(){format!("/api/movies?type={}&page=1",kind)}else{format!("/api/movies?q={}&page=1",enc(&q))};spawn_local(async move{match Request::get(&url).send().await{Ok(r)=>match r.json::<MovieList>().await{Ok(d)=>{sm.set(d.items);sn.set(String::new())},Err(_)=>sn.set("Không đọc được dữ liệu phim.".into())},Err(_)=>sn.set("Không thể kết nối nguồn phim.".into())}sl.set(false);});};
 let open_cb=Callback::new(move|m:Movie|{let slug=m.slug.clone();ss.set(Some(m));sd.set(None);sp.set(String::new());spawn_local(async move{if let Ok(r)=Request::get(&format!("/api/movie/{}",slug)).send().await{if let Ok(d)=r.json::<Detail>().await{sd.set(Some(d));}}});});
 Effect::new(move |_|load(String::new(),"phim-moi-cap-nhat".into()));
 Effect::new(move |_|{for (index,(_,_,kind)) in shelf_defs.clone().into_iter().enumerate(){let url=format!("/api/movies?type={}&page=1",kind);let set=shs;spawn_local(async move{if let Ok(response)=Request::get(&url).send().await{if let Ok(data)=response.json::<MovieList>().await{set.update(|all|{if let Some(shelf)=all.get_mut(index){shelf.items=data.items;}});}}});}});
 view!{<div class="shell">
 <header class="top" id="top"><a class="brand" href="#" on:click=move |_|{ss.set(None);st.set("home".into());}><b>XP</b><span class="brand-copy">XemPhim<small>Kho phim hay, cập nhật mỗi ngày</small></span></a><div><button class="round" on:click=move |_|sn.set("Bạn cần đăng nhập để đồng bộ thông báo.".into())>N</button><button class="round avatar" on:click=move |_|sn.set("Tài khoản sẽ được bổ sung ở bản tiếp theo.".to_string())>G</button></div></header>
 {move||if let Some(m)=selected.get(){let film=m.clone();view!{<main class="detail"><button class="back" on:click=move |_|{ss.set(None);sd.set(None);sp.set(String::new());}>Back Quay lại</button><section class="detailhero" style:background-image=move||format!("linear-gradient(90deg,#090812 0%,#090812bb 60%,#09081244),linear-gradient(0deg,#090812,transparent),url('{}')",film.backdrop)><div><small>PHIM TRỰC TUYẾN - CẬP NHẬT MỚI</small><h1>{film.name.clone()}</h1><p class="muted">{film.origin_name.clone()}</p><div class="meta">{film.year.map(|v|v.to_string()).unwrap_or_default()} / {film.quality.clone()} / {film.current_episode.clone()} / {film.time.clone()}</div><button class="cta" on:click=move |_|{if let Some(d)=detail.get(){if let Some(s)=d.servers.first(){if let Some(e)=s.episodes.first(){sp.set(if e.embed.is_empty(){e.m3u8.clone()}else{e.embed.clone()});}}}}>Play Xem ngay</button></div></section>
 {move||if !playing.get().is_empty(){let src=playing.get();view!{<section class="player"><div class="playerhead"><b>Đang phát</b><button class="plain" on:click=move |_|sp.set(String::new())>Đóng Close</button></div><div class="frame"><iframe src=src title="Trình phát phim" allow="autoplay; fullscreen; picture-in-picture" allowfullscreen=true></iframe></div></section>}.into_any()}else{view!{<div></div>}.into_any()}}
 <section class="details">{move||detail.get().map(|d|view!{<h2>{d.movie.name}</h2><p class="description">{d.movie.content}</p><p class="muted">Diễn viên: {d.movie.actors.join(", ")}</p><p class="muted">Đạo diễn: {d.movie.directors.join(", ")}</p><h3>Chọn tập phim</h3>{d.servers.iter().map(|server|{let name=server.name.clone();let eps=server.episodes.clone();view!{<p class="server">{name}</p><div class="episodes">{eps.iter().map(|e|{let label=e.name.clone();let src=if e.embed.is_empty(){e.m3u8.clone()}else{e.embed.clone()};view!{<button on:click=move |_|sp.set(src.clone())>{label}</button>}}).collect_view()}</div>}}).collect_view()}})}</section></main>}.into_any()}else{view!{<main><section class="hero-card-wrap"><div class="hero-card" style:background-image=move || movies.get().get(hero_index.get()).map(|m|format!("linear-gradient(180deg,rgba(8,8,18,.10),rgba(8,8,18,.2) 35%,rgba(8,8,18,.94) 100%),url('{}')",if m.backdrop.is_empty(){m.poster.clone()}else{m.backdrop.clone()})).unwrap_or_else(||"linear-gradient(145deg,#191b24,#090812)".into())><div class="hero-card-top"><span class="hero-kicker">PHIM NỔI BẬT</span><button class="hero-bell" on:click=move |_|sn.set("Bạn cần đăng nhập để đồng bộ thông báo.".into()) aria-label="Thông báo">N<span></span></button></div><div class="hero-card-content"><small>* PHIM ĐƯỢC ĐỀ XUẤT</small><h1>{move || movies.get().get(hero_index.get()).map(|m|m.name.clone()).unwrap_or_else(||"Khám phá thế giới điện ảnh".into())}</h1><p>{move || movies.get().get(hero_index.get()).map(|m|m.origin_name.clone()).filter(|s|!s.is_empty()).unwrap_or_else(||"Những bộ phim mới nhất, cập nhật mỗi ngày.".into())}</p><div class="hero-actions"><button class="hero-btn-primary" on:click=move |_|{if let Some(m)=movies.get().get(hero_index.get()).cloned(){open_cb.run(m);}else{st.set("single".into());load(String::new(),"phim-le".into());}}>Play Xem phim</button><button class="hero-btn-secondary" on:click=move |_|sn.set("Đăng nhập để lưu phim vào tủ phim.".into())>+ Tủ phim</button></div></div><div class="hero-thumbs">{move || movies.get().iter().take(6).enumerate().map(|(i,m)|{let idx=i;let poster=m.poster.clone();let title=m.name.clone();let aria_title=title.clone();let alt_title=title.clone();view!{<button class:active=move || hero_index.get()==idx on:click=move |_|shi.set(idx) aria-label=aria_title><img src=poster alt=alt_title loading="lazy"/></button>}}).collect_view()}</div></div></section><section class="topic-strip"><div class="topic-heading">Bạn đang quan tâm gì</div><div class="topic-list"><a href="#shelf-anime">Anime</a><a href="#shelf-action">Hành động</a><a href="#shelf-horror">Kinh dị</a><a href="#shelf-romance">Tình cảm</a><a href="#shelf-mystery">Trinh thám</a><a href="#shelf-costume">Cổ trang</a><a href="#shelf-korea">Phim Hàn</a></div></section><section class="catalog"><div class="heading"><div><small>ĐỀ XUẤT CHO BẠN</small><h2>{move||match tab.get().as_str(){"single"=>"Phim lẻ","series"=>"Phim bộ","search"=>"Tìm kiếm phim",_=>"Phim mới cập nhật"}}</h2></div><button class="plain" on:click=move |_|load(String::new(),"phim-moi-cap-nhat".into())>Làm mới Refresh</button></div><div class="search"><span>Search</span><input placeholder="Tìm tên phim, diễn viên..." prop:value=move||query.get() on:input=move|ev|sq.set(event_target_value(&ev)) on:keydown=move|ev|if ev.key()=="Enter"{load(query.get(),String::new());st.set("search".into());}/><button on:click=move |_|{load(query.get(),String::new());st.set("search".into());}>Tìm kiếm</button></div>{move||if !notice.get().is_empty(){view!{<p class="notice">{notice.get()}</p>}.into_any()}else{view!{<div></div>}.into_any()}}{move||if loading.get(){view!{<div class="grid">{(0..9).map(|_|view!{<div class="skeleton"></div>}).collect_view()}</div>}.into_any()}else{let items=movies.get();if items.is_empty(){view!{<p class="muted">Chưa tìm thấy phim phù hợp.</p>}.into_any()}else{view!{<div class="grid">{items.into_iter().map(|m|{let item=m.clone();let title=m.name.clone();let poster=m.poster.clone();let year=m.year.map(|v|v.to_string()).unwrap_or_default();let ep=m.current_episode.clone();view!{<button class="card" on:click=move |_|open_cb.run(item.clone())><div class="poster"><img src=poster alt=title.clone() loading="lazy"/><b>{m.quality.clone()}</b><i>Play</i></div><strong>{title}</strong><small>{year} / - / {ep}</small></button>}}).collect_view()}</div>}.into_any()}}}</section>{move || home_shelves.get().into_iter().filter(|shelf|!shelf.items.is_empty()).map(|shelf|view!{<HomeShelf id=shelf.id title=shelf.title items=shelf.items on_open=open_cb/>}).collect_view()}</main>}.into_any()}}
 <nav class="dock"><button class:active=move||tab.get()=="home" on:click=move |_|{ss.set(None);st.set("home".into());load(String::new(),"phim-moi-cap-nhat".into());}><b>Home</b><small>Khám phá</small></button><button class:active=move||tab.get()=="single" on:click=move |_|{ss.set(None);st.set("single".into());load(String::new(),"phim-le".into());}><b>Film</b><small>Phim lẻ</small></button><button class:active=move||tab.get()=="series" on:click=move |_|{ss.set(None);st.set("series".into());load(String::new(),"phim-bo".into());}><b>Series</b><small>Phim bộ</small></button><button class:active=move||tab.get()=="search" on:click=move |_|{ss.set(None);st.set("search".into());}><b>Search</b><small>Tìm kiếm</small></button></nav></div>}
}
fn main(){mount_to_body(App);}
